@startuml

class Department {
  + Name : string
}

class Room {
  + Number : int
}

class Bed {
  + Category : string
}

class Category {
  + Price : double
}

class Inhabitant {
  + Name : string
  + BasicIdentificationData : string
  + NeedsForHelp : string
}

class Stay {
  + Type : string
  + DateOfIntake : date
}

class RegistrationProcess {
  + Questions : string
}

class Assessment {
  + Results : string
}

class WaitingList {
  + Position : int
}

class Proposal {
  + Accepted : boolean
  + Invalidated : boolean
}

class Invoice {
  + Total : double
  + OutstandingAmount : double
  + PaymentReceived : event
}

class CreditNote {}

Department "1" -- "*" Room
Room "1" -- "*" Bed
Category "1" -- "*" Bed
Inhabitant "0..*" -- "*" Stay
Stay "1" -- "1" Category
RegistrationProcess "1" -- "*" Inhabitant
Assessment "1" -- "*" Inhabitant
WaitingList "1" -- "*" Inhabitant
Proposal "1" -- "*" Inhabitant
Invoice "1" -- "*" Inhabitant

@enduml

